package kindleroid.launcher;
import android.os.Bundle;import android.view.*;import android.widget.*;import android.app.*;import java.io.*;
/** Persistent results written by the existing installer; never executes file contents. */
public class InstallActivity extends UiPage {
 private String reason(String raw){if(raw.contains("NOT_APK")||raw.contains("INVALID_APK")||raw.contains("NO_CERTIFICATES"))return "文件不完整，请重新复制。";if(raw.contains("OLDER_SDK"))return "应用需要更新的 Android 版本。";if(raw.contains("NO_MATCHING_ABIS"))return "应用不支持此设备，请更换安装包。";if(raw.contains("INSUFFICIENT_STORAGE"))return "存储空间不足，请清理后重试。";if(raw.contains("VERSION_DOWNGRADE"))return "已安装更新版本。";if(raw.contains("UPDATE_INCOMPATIBLE"))return "应用签名不同，无法覆盖安装。";return "安装未完成，点按查看详情";}
 protected void onCreate(Bundle b){super.onCreate(b);page("安装记录");TextView summary=text("",19);summary.setTextColor(0xff333333);body.addView(summary,lp(-1,60));int pass=0,fail=0;File f=new File("/data/local/tmp/kobodroid-install.tsv");
 if(f.length()>0&&f.length()<=65536)try{BufferedReader in=new BufferedReader(new FileReader(f));try{String line;int rows=0;while((line=in.readLine())!=null&&rows++<100){String[] fields=line.split("\\t",3);if(fields.length!=3||!(fields[0].equals("PASS")||fields[0].equals("FAIL")))continue;boolean ok=fields[0].equals("PASS");if(ok)pass++;else fail++;LinearLayout item=row();item.setGravity(Gravity.TOP);item.setPadding(0,px(26),0,px(26));ImageView icon=new ImageView(this);icon.setImageDrawable(UiStyle.icon(this,ok?"check":"alert"));item.addView(icon,lp(28,28));LinearLayout words=new LinearLayout(this);words.setOrientation(1);words.setPadding(px(16),0,0,0);TextView name=text(fields[1],26);name.setMaxLines(2);name.setEllipsize(android.text.TextUtils.TruncateAt.END);words.addView(name);TextView state=text(ok?"已安装":reason(fields[2]),19);state.setTextColor(0xff333333);LinearLayout.LayoutParams sp=lp(-1,-2);sp.topMargin=px(14);words.addView(state,sp);item.addView(words,new LinearLayout.LayoutParams(0,-2,1));if(!ok){final String detail=fields[2];item.setOnClickListener(new View.OnClickListener(){public void onClick(View v){UiStyle.showFlat(new AlertDialog.Builder(InstallActivity.this).setTitle("安装未完成").setMessage(detail.length()==0?"文件可能不完整或与系统不兼容，请重新复制后重试。":detail).setPositiveButton("完成",null).create());}});}body.addView(item);rule(body);}}finally{in.close();}}catch(IOException e){}
 summary.setText(pass+fail==0?"暂无安装记录":pass+" 个已安装 · "+fail+" 个未完成");Button help=action("安装说明",false,new View.OnClickListener(){public void onClick(View v){UiStyle.showFlat(new AlertDialog.Builder(InstallActivity.this).setTitle("安装说明").setMessage("将 APK 复制到 Kobo 存储根目录的 Kobodroid-APK 文件夹，下次进入时安装。成功文件保留在 installed，未完成的文件保留在 failed。").setPositiveButton("完成",null).create());}});LinearLayout.LayoutParams hp=lp(180,54);hp.topMargin=px(28);body.addView(help,hp);bottom("完成",new View.OnClickListener(){public void onClick(View v){finish();}});
 }
}
